// Shared entry lessons: no job, robot, GPU or prior machine-learning knowledge assumed.
const section=(title,...paragraphs)=>({title,paragraphs});
const check=(prompt,options,answer,explanation)=>({prompt,options,answer,explanation});
export const foundations=[
 {id:'predict',title:'从一个计算规则开始：输入、参数和预测',hours:[2,4],exerciseId:'daily-w1-d2',
  question:'一件商品按重量计价。拿到重量后，程序怎样给出价格？',
  before:'只需要能做加减乘除。没有写过代码也可以从下面的逐行解释开始。',
  goal:'读懂并写出一个函数；区分输入数据、共享参数、输出和真实答案。',
  terms:[['输入 x','本次交给程序的数，例如重量 2。'],['参数 w、b','计算规则里共用的数，例如每单位重量价格 3、基础费用 1。'],['预测','程序根据当前规则算出的结果；它不保证等于真实价格。'],['函数','给一段计算起名字，接收输入并返回结果，方便反复调用。'],['列表与批次','[1,2] 是按顺序放置的两个数。批次是一起处理的多条样本。']],
  sections:[
   section('先算一次，不急着训练','假设价格规则是 y=w*x+b。w=3、b=1，重量 x=2 时，预测就是 3×2+1=7。换成重量 1，预测为 4。两条商品共用同一组 w、b；重量属于样本，w、b 属于模型。','现在我们只是手动设置规则。程序没有看真实价格，也没有根据错误修改参数，因此这里只发生了推理。模型不一定是巨大的神经网络；我们从一个能够检查的小预测器开始。'),
   section('第一次接触 Python：先读这几个符号','Python 用 * 表示乘法，+ 表示加法。x = 2 是给名字 x 赋值；它不是证明两个式子永远相等。print(x) 把值显示出来，方便观察。文本要放在引号里，数值一般不用引号。','def 开始定义函数，括号里列出它接收的输入，冒号后的缩进属于函数内部。return 把结果交给调用者。只写 print 会显示数字，却没有按要求返回结果；后面的评测器就拿不到预测。'),
   section('从一个数扩展到一批数','xs=[1,2] 存了两条输入。先建立 outputs=[]，再用 for x in xs: 依次取出每个数。outputs.append(...) 把新结果放到列表末尾。计算完所有样本后再 return outputs。','缩进决定 return 是否在循环里面。若在循环内，处理第一条就结束了。输出顺序必须与输入一致：输入 [1,2] 应返回 [4,7]，否则后续会把一个商品的预测与另一个商品的真实价格比较。'),
   section('做完应该能迁移什么','这个预测接口可以用于价格、传感器或任何合适的数字关系。之后换成神经网络，输入和参数仍然是不同角色；图片和文字也需要先变成数值表示。','先完成下方预测函数，再改一条输入和一个参数，分别观察结果。暂时不会列表推导式没有关系，普通 for 循环同样能完成全部检查。')
  ],
  example:{code:'def quote(x, w, b):\n    return w * x + b\n\nxs = [1, 2]\noutputs = []\nfor x in xs:\n    outputs.append(quote(x, 3, 1))\nprint(outputs)\n',output:'[4, 7]\n'},
  worked:['输入列表是 [1,2]，参数是 w=3、b=1。','第一个预测 3×1+1=4，第二个预测 3×2+1=7。','只把 w 改成 4，输出变成 [5,9]；改参数和换输入是两种操作。'],
  practice:['实现下方 predict；先运行样例，再提交全部检查。','把输入换成空列表：没有样本时应返回 []，不能返回 None。','在记录里分别写出一条输入、一个参数和一个预测，并说明函数返回了什么。'],
  recovery:'报缩进错误时，先对齐同一层的语句；只有一个输出时，检查 return 是否提前结束了循环。先用 print 观察中间值，最后仍需 return 返回列表。',
  checks:[check('predict([2],3,1) 中，哪一个是输入样本？',['2','3','1'],0,'2 是本次商品的重量。3 和 1 是在所有样本间共用的参数。'),check('程序反复调用同一预测函数，参数没有改变，就一定在训练吗？',['是，运行次数多就是训练','不是，需要反馈与参数更新'],1,'这时只是在重复推理。下一节才加入真实答案、误差和更新。')],
  next:'我们能算预测了，但参数还靠手猜。下一步让真实答案告诉程序哪里错了、如何调整。',
  links:[{href:'#/labs/gradient',label:'可选：观察参数改变时的预测曲线'}]
 },
 {id:'train',title:'根据错误调整：损失、梯度和一次训练',hours:[2,4],exerciseId:'daily-w1-d4',
  question:'预测价格是 0，真实价格是 3。除了说“错了”，程序还能做什么？',before:'先能解释上一节的输入、参数和预测，并读懂列表与循环。',goal:'亲手完成一次参数更新，区分损失、梯度和学习率。',
  terms:[['标签／目标 y','数据中记录的真实答案，例如真实价格 3。'],['误差 e','预测减去真实答案。预测 0、答案 3，则误差为 -3。'],['损失 loss','把错误汇总成一个数。本例把每个误差平方后取平均。'],['梯度','参数在当前位置微小变化时，损失变化的方向和速率。'],['学习率 lr','把梯度转为实际更新幅度的系数。'],['平均','总和除以数量；Python 中可以用 sum(values)/len(values)。']],
  sections:[
   section('为什么不直接平均正负误差','两条样本分别错 -2 与 +2，直接平均得到 0，但两条都没有预测对。我们先平方：4 与 4，再平均得到 4。这就是均方误差 MSE。它是一个检查当前模型的数字，不是模型里待训练的参数。','真实答案来自数据，不是模型自己说了算。首先检查输入与答案一一对应；配错了标签，即使训练程序能运行，也可能学到错误关系。'),
   section('为什么要看局部变化，而不随便改参数','先只考虑一个参数 w、输入 x=1、b=0、目标 3。此时 loss=(w-3)²。w=0 时 loss=9；把 w 略微增加到 0.01，loss=8.9401，变小了。当前位置的梯度为 -6，表示小幅增加 w 会降低损失。','一般的 y_hat=w*x+b 也可以这样分析。本例整批样本的 dw 是 2*e*x 的平均，db 是 2*e 的平均。这两个公式是平方误差对两个参数的导数。数学在这里用于回答“往哪边动”；先用单样本核对符号，再扩展到多条。'),
   section('把方向变成一次更新','更新规则是 new_w=w-lr*dw，new_b=b-lr*db。减去梯度代表尝试往损失下降的方向走。学习率过大会越过合适区域，过小则进展缓慢，所以不能保证每个学习率都让损失下降。','两个梯度必须用同一组旧参数计算完，再同时更新。学习率为 0 时，参数保持不动，但仍能计算当前损失。返回 loss_before 表示更新前的误差，不能悄悄换成更新后的值。'),
   section('先补齐本题需要的 Python，再连接真实训练器','zip(xs,ys) 按位置把输入与答案配成对；len(xs) 是样本数，sum(...) 计算总和。**2 与 e*e 都可表示平方。返回 (new_w,new_b,loss_before) 是返回三个值组成的元组。','实际神经网络通常由 PyTorch 自动求导：forward 计算预测，loss 汇总错误，backward 算梯度，optimizer.step 改参数。它们仍然对应这里的四步，不会自动替你修复标签和评测。批次、shape 与自动求导将在公共进阶课里接着学。')
  ],
  example:{code:'x, target = 1, 3\nw, b, lr = 0, 0, 0.1\nerror = w * x + b - target\nloss_before = error * error\ndw, db = 2 * error * x, 2 * error\nnew_w, new_b = w - lr * dw, b - lr * db\nprint(loss_before)\nprint(round(new_w, 2), round(new_b, 2))\n',output:'9\n0.6 0.6\n'},
  worked:['旧 w=b=0，输入 1、答案 3；预测 0，误差 -3，loss=9。','dw=db=-6；lr=0.1，因此 w 和 b 都更新到 0.6。','新预测为 1.2，新损失为 3.24。接口要求返回的 loss_before 仍是 9。'],
  practice:['先在纸上或记录里算一次单样本更新，再实现下方函数。','测试 lr=0：参数不动，但误差不会凭空消失。','在梯度实验中只改变学习率，记录下降、缓慢或发散的实际现象。'],
  recovery:'结果符号反了，检查是否使用“旧参数减去学习率乘梯度”；两项更新对不上，检查是否中途修改了 w。多条样本时，平方误差和两个梯度都要除以样本数。',
  checks:[check('误差分别为 -2 和 +2，本例的均方误差是多少？',['0','2','4'],2,'先平方后平均：(4+4)/2=4，不能先平均再平方。'),check('梯度为 -6，旧参数 0，学习率 0.1，更新后是多少？',['-0.6','0.6','6'],1,'0-0.1×(-6)=0.6。梯度符号与更新公式要一起看。')],
  next:'训练误差下降只说明更适合训练数据。下一节换一批样本，检查能否真的解决新问题。',
  links:[{href:'#/labs/gradient',label:'运行学习率与梯度交互实验'},{href:'#/lesson/w3-l2',label:'进阶：张量、自动求导与训练循环'}]
 },
 {id:'evaluate',title:'换一批数据检验：基线、验证与失败',hours:[2,4],exerciseId:'daily-w1-d6',
  question:'练习题答对了，换成没见过的题还会对吗？',before:'能区分预测、标签、损失和参数更新。',goal:'实现一个不修改参数的评测器，用证据决定下一步改什么。',
  terms:[['训练集','参与计算梯度、更新参数的数据。'],['验证集','帮助比较方案与选择设置的数据，不直接用于本次梯度更新。'],['测试集','方案确定后使用的保留数据，减少反复调参带来的乐观判断。'],['基线','一个明确的比较对象，例如始终预测训练标签的平均值。'],['泛化','模型对未参与训练的新样本是否仍然有效。'],['数据泄漏','评测所需的独立信息提前进入训练或选择过程，造成虚假的好成绩。']],
  sections:[
   section('同一模型，换一批输入','训练时可以根据训练答案改 w、b；验证时先固定它们，只计算预测和误差。如果评测器看到一个答案就更新一次参数，它已经变成了继续训练，不能再说明原模型在新数据上的效果。','反复用验证集选方案也会影响判断，因此最终测试集应尽量保留到方案确定之后。图片的近重复、同一视频的邻帧、同一道题的改写，都可能使随机划分看起来独立、实际上高度相似。'),
   section('为什么还需要一个简单对手','假设所有价格都接近 10，始终预测 10 就可能得到很低的误差。复杂网络也达到这个误差，并不意味着它利用了输入信息。我们让模型与常数基线在完全相同的验证样本上比较。','基线的数值只能从训练数据或事先定义的规则确定。不要先看验证答案，算一个最合适的常数，再把它当作独立基线。公平比较还需要相同的指标、样本和计时范围。'),
   section('均值之外，保留具体失败','模型总体更准，也可能在大重量商品上持续偏低。把错误按输入范围、类别或场景分组，才能判断问题是数据覆盖不足、直线表达不了弯曲关系，还是更新出了问题。','下一步不默认增加模型大小。先检查单位、标签、时间对齐，再检查能否拟合少量数据。如果同样的输入缺少决定答案的信息，增加参数也不能凭空获得这些条件。'),
   section('把结果作为一个接口交出去','本题返回字典，例如 {"model_mse":0,"baseline_mse":4.5}。字典把名字和数值对应起来，调用者可以通过 result["model_mse"] 读取模型误差。字符串键需要引号。','后来语言、图像、视频和机器人会有不同的评测任务。指标名称只是起点：先说清输入、输出与成功标准，再选指标。一个语言问答榜单不能替代生成画面质量或机器人任务成功率。')
  ],
  example:{code:'xs, ys = [1, 2], [3, 6]\npredictions = [3, 6]\nerrors = []\nfor prediction, target in zip(predictions, ys):\n    errors.append((prediction - target) ** 2)\nresult = {"model_mse": sum(errors) / len(errors)}\nprint(result["model_mse"])\n',output:'0.0\n'},
  worked:['验证输入 [1,2]，真实答案 [3,6]，w=3、b=0，模型预测 [3,6]。','常数基线为 3，预测 [3,3]；平方误差为 [0,9]，平均 4.5。','同一验证集上，模型 MSE=0、基线 MSE=4.5。结论仅覆盖这批样本，还需进一步检查新范围与失败组。'],
  practice:['实现评测器，分别报告模型和基线的均方误差。','构造一条基线比模型更好的样本，确认程序没有预设模型一定赢。','记录一次“只改一个变量”的后续实验：失败是什么、改哪里、如何比较。'],
  recovery:'结果异常时，先手算两条样本；确认是误差平方的平均。检查验证函数没有修改参数，两个方案没有使用不同的样本集合。',
  checks:[check('验证函数一边看验证答案一边更新参数，还在评测原模型吗？',['是','不是，已经发生了继续训练'],1,'验证与训练的职责必须分开。否则无法判断原模型对未见数据的表现。'),check('选择更复杂结构前，哪项证据更有用？',['名字更新、更流行','相同数据和指标下的失败分组与对照'],1,'结构改动需要回应具体问题；名称本身不能证明改进。')],
  next:'公共入门形成了“预测 → 更新 → 验证”的闭环。接着补齐张量与小神经网络，再按兴趣选择语言、图像、视频或行动任务。',
  links:[{href:'#/day/w1-d7',label:'综合编程：把训练与验证接成一个程序'},{href:'#/lesson/w4-l1',label:'进阶：从线性模型换到神经网络'},{href:'#/paths',label:'查看各方向的前置能力与实战'}]
 }
];
